from gurobipy import *

def solve_problem():
    m = Model("Battlefield_Logistics")
    m.setParam("TimeLimit", 100)  # Set time limit to 100 seconds

    # Data
    depots = list(range(10))  # D0..D9
    units = list(range(7))  # U0..U6
    supplies = list(range(2))  # S0..S1
    days = list(range(3))  # Day0..Day2

    demands = [[[41.88, 47.24, 33.97], [22.73, 17.32, 41.33]], [[48.69, 38.24, 25.15], [29.06, 35.29, 41.65]], [[47.35, 11.48, 22.89], [34.8, 15.01, 16.02]], [[33.73, 39.88, 49.14], [30.88, 40.24, 23.21]], [[18.56, 21.14, 35.63], [34.13, 44.43, 28.32]], [[45.87, 49.99, 36.26], [28.86, 40.08, 28.08]], [[34.02, 15.94, 10.23], [39.19, 46.81, 34.97]]]
    depot_supplies = [[[33.6, 18.21, 30.32], [22.28, 28.74, 22.13]], [[27.4, 26.47, 24.02], [18.51, 30.11, 31.35]], [[39.16, 19.79, 26.17], [32.15, 32.2, 24.66]], [[40.19, 18.9, 23.98], [19.2, 32.52, 21.86]], [[37.66, 26.36, 23.91], [29.65, 29.38, 20.84]], [[26.36, 27.17, 30.75], [26.81, 32.13, 27.99]], [[36.63, 33.45, 28.83], [21.94, 20.21, 28.84]], [[36.12, 30.73, 22.59], [28.07, 29.46, 28.63]], [[32.27, 26.43, 25.87], [21.39, 22.82, 21.19]], [[32.11, 19.88, 24.75], [28.48, 28.17, 25.81]]]
    transport_costs = [[1.52, 4.29, 3.2, 4.83, 2.36, 4.79, 4.66], [3.02, 4.74, 3.27, 2.2, 4.38, 4.7, 2.19], [2.32, 4.62, 2.36, 4.03, 3.11, 3.07, 1.71], [3.29, 2.91, 1.32, 2.46, 1.68, 4.29, 4.34], [3.89, 3.54, 1.76, 2.18, 1.05, 2.16, 1.17], [4.56, 3.44, 1.69, 1.66, 3.82, 1.37, 1.77], [1.16, 2.12, 4.83, 2.44, 2.73, 1.06, 4.97], [3.94, 3.47, 3.64, 4.08, 4.6, 3.52, 1.12], [1.76, 3.09, 2.29, 4.97, 2.75, 1.02, 3.17], [3.52, 4.87, 2.66, 3.36, 4.38, 1.76, 1.55]]
    risk_costs = [[93.56, 101.93, 99.51, 164.74, 152.98, 94.23, 193.61], [194.54, 172.45, 190.31, 85.19, 113.39, 120.04, 119.3], [111.67, 95.47, 51.23, 64.77, 141.27, 189.94, 164.54], [178.38, 106.04, 123.76, 96.85, 81.91, 196.21, 138.62], [196.14, 114.16, 112.89, 119.52, 176.96, 164.05, 160.26], [159.32, 78.95, 92.91, 136.05, 55.3, 105.95, 145.11], [128.26, 141.89, 130.21, 139.54, 111.13, 59.69, 97.32], [112.56, 96.85, 73.69, 67.26, 107.61, 122.44, 188.31], [161.86, 115.72, 86.28, 52.05, 136.41, 65.75, 188.65], [99.54, 99.29, 52.65, 60.29, 140.01, 177.17, 123.15]]
    supply_volumes = [1.86, 0.79]
    penalty_costs = [66.14, 87.77]
    vehicle_cost = 10.0
    vehicle_capacity = 127.0
    total_vehicles = 14

    # Decision variables
    # Flow_D{d}_U{u}_S{s}_Day{t}: Amount of supply s from depot d to unit u on day t
    flows = {}
    for t in days:
        for d in depots:
            for u in units:
                for s in supplies:
                    flows[(d, u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Flow_D{d}_U{u}_S{s}_Day{t}")

    # Slack_U{u}_S{s}_Day{t}: Shortage of supply s at unit u on day t
    slacks = {}
    for t in days:
        for u in units:
            for s in supplies:
                slacks[(u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Slack_U{u}_S{s}_Day{t}")

    # Veh_D{d}_U{u}_Day{t}: Number of vehicles on route d->u on day t
    vehicles = {}
    for t in days:
        for d in depots:
            for u in units:
                vehicles[(d, u, t)] = m.addVar(lb=0.0, vtype=GRB.INTEGER, name=f"Veh_D{d}_U{u}_Day{t}")

    # Route_D{d}_U{u}_Day{t}: Route d->u is active on day t (binary)
    routes = {}
    for t in days:
        for d in depots:
            for u in units:
                routes[(d, u, t)] = m.addVar(vtype=GRB.BINARY, name=f"Route_D{d}_U{u}_Day{t}")

    # Objective: Minimize total cost (transport + penalty + vehicle + risk)
    obj = quicksum(
        transport_costs[d][u] * flows[(d, u, s, t)]
        for t in days for d in depots for u in units for s in supplies
    )
    obj += quicksum(
        penalty_costs[s] * slacks[(u, s, t)]
        for t in days for u in units for s in supplies
    )
    obj += quicksum(
        vehicle_cost * vehicles[(d, u, t)]
        for t in days for d in depots for u in units
    )
    obj += quicksum(
        risk_costs[d][u] * routes[(d, u, t)]
        for t in days for d in depots for u in units
    )
    m.setObjective(obj, GRB.MINIMIZE)

    # Depot capacity constraints: Total outflow <= supply
    for t in days:
        for d in depots:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for u in units) <= depot_supplies[d][s][t],
                    name=f"DepotCap_D{d}_S{s}_Day{t}"
                )

    # Demand constraints: Inflow + slack >= demand
    for t in days:
        for u in units:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for d in depots) + slacks[(u, s, t)] >= demands[u][s][t],
                    name=f"Demand_U{u}_S{s}_Day{t}"
                )

    # Vehicle capacity constraints: Total volume <= vehicles * capacity
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    quicksum(supply_volumes[s] * flows[(d, u, s, t)] for s in supplies) <= vehicle_capacity * vehicles[(d, u, t)],
                    name=f"VehCap_D{d}_U{u}_Day{t}"
                )

    # Route activation constraints: vehicles <= total_vehicles * route
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    vehicles[(d, u, t)] <= total_vehicles * routes[(d, u, t)],
                    name=f"RouteAct_D{d}_U{u}_Day{t}"
                )

    # Fleet size constraints: Total vehicles <= total_vehicles
    for t in days:
        m.addConstr(
            quicksum(vehicles[(d, u, t)] for d in depots for u in units) <= total_vehicles,
            name=f"FleetSize_Day{t}"
        )

    m.optimize()
    return m
